FROM scc_base_quicksearch_config
WHERE NAME IN ('pr_requirement_head2');
FROM (SELECT t.*, CONCAT(ifnull(t.apply_by_nickname,\'\'), \'(\', ifnull(t.APPLY_BY,\'\'), \')\') as APPLY_USER_NAME,
             b.ORG_BU_ID,
             b.ORG_BU_CODE,
             b.ORG_BU_NAME,
             b.REQUIRE_FROM,
             b.PROJECT_NAME,
             b.TOTAL_AMOUNT_BY_TEN_KILO,
             b.INVEST_NO,
             b.NO_REPORT_MONTH_PLAN_REASON,
             b.NEED_PUBLIC,
             CONCAT(ifnull(c.FULL_NAME,\'\'), IF(c.USERNAME IS NOT NULL, \'(\', NULL), ifnull(c.USERNAME,\'\'),IF(c.USERNAME IS NOT NULL, \')\', NULL) ) as RESPONSIBILITY_USER_NAME
      FROM scc_pr_requirement_head t
               LEFT JOIN scc_npm_pr_require_head b ON t.REQUIREMENT_HEAD_ID = b.REQUIREMENT_HEAD_ID
               LEFT JOIN scc_npm_pr_require_group c on t.REQUIREMENT_HEAD_ID =c.REQUIREMENT_HEAD_ID and c.GROUP_TYPE=\'VENDOR\'
      WHERE  t.AUDIT_STATUS = \'APPROVED\'
      ORDER BY t.CREATION_DATE DESC) t where 1=1 and t.REQUIREMENT_HEAD_NUM like :query', null, null, null, null, null, 'SELECT t.*
FROM (SELECT t.*, CONCAT(ifnull(t.apply_by_nickname,\'\'), \'(\', ifnull(t.APPLY_BY,\'\'), \')\') as APPLY_USER_NAME,
             b.ORG_BU_ID,
             b.ORG_BU_CODE,
             b.ORG_BU_NAME,
             b.REQUIRE_FROM,
             b.PROJECT_NAME,
             b.TOTAL_AMOUNT_BY_TEN_KILO,
             b.INVEST_NO,
             b.NO_REPORT_MONTH_PLAN_REASON,
             b.NEED_PUBLIC,
             CONCAT(ifnull(c.FULL_NAME,\'\'), IF(c.USERNAME IS NOT NULL, \'(\', NULL), ifnull(c.USERNAME,\'\'),IF(c.USERNAME IS NOT NULL, \')\', NULL) ) as RESPONSIBILITY_USER_NAME
      FROM scc_pr_requirement_head t
