            LEFT JOIN scc_npm_pr_require_group c on t.REQUIREMENT_HEAD_ID =c.REQUIREMENT_HEAD_ID and c.GROUP_TYPE=\'VENDOR\'
      WHERE  t.AUDIT_STATUS = \'APPROVED\'
